import 'package:window_manager/window_manager.dart';

void main() async {
  await windowManager.ensureInitialized();
  final window = WindowManager.instance.getCurrent()!;
  window.title = 'My App';
  window.setSize(const Size(1000, 700).toNative(), false);
  window.center();
  window.show();
}
